from lib import *
S = SS('w60')
steps = [
    step("先看开关。net.inet.tcp.fastopen = 3(位掩码:1 客户端、2 服务端,都开),fastopen_backlog = 10。服务端要在 listen() 之后才能对监听套接字 setsockopt(TCP_FASTOPEN, 1):listen() 之前设置得到 EINVAL,之后成功、读回 1。客户端在 macOS 上不是 Linux 的 sendto + MSG_FASTOPEN(Python 的 socket 模块里没有 MSG_FASTOPEN),而是系统调用 connectx,带上 CONNECT_DATA_IDEMPOTENT 标志和一块数据;Python 没有封装,我用 ctypes 直接调用 libc 的 connectx。", t=tl(S(1)), mark=lidx(S(1), 'listen() 之前对监听套接字', 'listen() 之后 setsockopt'), done=lidx(S(1), 'net.inet.tcp.fastopen: 3', 'fastopen_backlog: 10', 'Python 的 socket 模块里有'), kv=KV([['net.inet.tcp.fastopen', '3(客户端 + 服务端)'], ['服务端', 'listen() 之后 setsockopt(0x105)'], ['客户端', 'connectx(ctypes 调用)']], ['客户端'])),
    step("换一个客户端从没用过的目的地做干净对照:lo0 上新加的别名 127.77.0.11,服务端不开 TFO,连续 8 次 connectx(各带 6 字节)。服务端 8 条数据全部收到(hello0 到 hello7)。8 个 SYN 全都一样:载荷 0 字节,选项 MSS / WS / TS / SACKok 之外多一个长度 2 的 TFO 选项(只请求 cookie,没有数据),SYN+ACK 里没有 TFO 选项——服务端没有响应这个请求。8 次都如此,客户端没有因为得不到 cookie 就不再尝试;数据是握手完成之后才发出的。(我最初在 127.0.0.1 上做这个对照,但那个目的地的 TFO 早已被客户端停用,SYN 里连请求 cookie 的选项都看不到,没有对照意义;原因见第七、八节。)", t=tl(S(2)), mark=lidx(S(2), '第 1 个', '第 8 个'), done=lidx(S(2), '服务端收到的数据'), kv=KV([['SYN 载荷', '8 次都是 0 字节'], ['SYN 的 TFO 选项', '8 次都带长度 2(请求 cookie)'], ['SYN+ACK', '没有 TFO 选项'], ['数据', '握手之后才发出']], ['SYN 的 TFO 选项'])),
    step("换一个没用过的目的地(本机 en0 的 IPv4 地址,发往它的包走 lo0),服务端开 TFO,连续 12 次 connectx,各带 7 字节。12 个 SYN 的载荷:[0, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7]。第 1 个连接 SYN 里只有长度 2 的 TFO 选项——客户端请求 cookie,服务端在 SYN+ACK 里给了 cookie;从第 2 个连接起,SYN 带着长度 10 的 TFO 选项(8 字节 cookie)和 7 字节数据。第 2 个连接的线上:+0.00 ms SYN 带 7 字节,+0.26 ms SYN+ACK 的 ack = SYN 的 seq + 8(SYN 占 1 + 数据 7 字节),+0.32 ms ACK,服务端在数据到达后 +0.47 ms 就回了 10 字节应答。12 条数据服务端全部正确收到。", t=tl(S(3)), mark=lidx(S(3), '12 个连接的 SYN 载荷', '12 个 SYN 的 TFO 选项长度', 'ack = SYN 的 seq + 8'), done=lidx(S(3), '服务端收到的数据 12 条', '第 2 个连接'), b=bars([['第 1 个连接 SYN 载荷', 0, '0 字节'], ['第 2~12 个连接 SYN 载荷', 7, '7 字节']], 7, mark=[1], done=[0]), kv=KV([['第 1 个', 'SYN 无数据,TFO 选项长 2(要 cookie)'], ['第 2~12 个', 'SYN 带 7 字节,TFO 选项长 10'], ['SYN+ACK 的 ack', 'seq + 8(确认了数据)']], ['第 2~12 个'])),
    step("省下多少时间:又换一个没用过的目的地(本机 en0 的链路本地 IPv6 地址),lo0 上每方向加 50 ms 延迟(RTT 100 ms)。4 次普通 connect + send:202 / 200 / 201 / 202 ms,中位 202 ms。4 次 connectx:205 / 101 / 100 / 103 ms,SYN 载荷 [0, 5, 5, 5]——第 1 次取 cookie,SYN 里没有数据,耗时 205 ms 和普通连接一样;后 3 次 SYN 带 5 字节,耗时中位 101 ms。省下 101 ms,正好约 1 个 RTT:数据在 SYN 里到达,服务端不用等握手完成就能回应,请求-应答少一个往返。", t=tl(S(4)), mark=lidx(S(4), '省下 101 ms', 'connectx(TFO)'), done=lidx(S(4), '普通 connect + send'), b=bars([['普通 connect + send', 202, '202 ms'], ['connectx(无 cookie)', 205, '205 ms'], ['connectx(SYN 带数据)', 101, '101 ms']], 205, mark=[2], done=[0, 1]), kv=KV([['普通 connect + send', '中位 202 ms'], ['第 1 次 connectx(取 cookie)', '205 ms'], ['后 3 次(SYN 带数据)', '中位 101 ms'], ['省下', '101 ms ≈ 1 个 RTT']], ['省下'])),
    step("真实服务器:对 example.com:80 用 connectx,把 56 字节的 HTTP 请求放进 SYN。3 次的 SYN 载荷都是 56 字节,TFO 选项长度 10(带 cookie——这台本机此前已经拿到过 example.com 的 cookie);服务器的 SYN+ACK 的 ack = SYN 的 seq + 57,即确认了 SYN 里的数据,说明 example.com 的服务器接受了 SYN 里的请求。从发起到收到响应第一批字节:267 / 243 / 248 ms;普通 connect + send 的 3 次是 386 / 378 / 476 ms。差不多省下一个 RTT。SYN+ACK 的选项里没有 TFO(原因没有查证)。", t=tl(S(5)), mark=lidx(S(5), 'connectx 第 1 次', 'connectx 到收到响应第一批字节'), done=lidx(S(5), 'connectx 第 2 次', 'connectx 第 3 次'), b=bars([['connectx 带数据', 248, '约 250 ms'], ['普通 connect + send', 386, '约 390 ms']], 476, mark=[0], done=[1]), kv=KV([['SYN 载荷', '56 字节(HTTP 请求)'], ['SYN+ACK 的 ack', 'seq + 57,数据被确认'], ['首字节', '267 / 243 / 248 ms'], ['普通连接', '386 / 378 / 476 ms']], ['SYN+ACK 的 ack'])),
    step("服务端密钥轮换(需要 root:sysctl net.inet.tcp.fastopen_key,值是 32 个十六进制字符,读回是空的,不能回读)。目的地 127.77.0.12,服务端开 TFO,先设密钥 K1:连接 1 请求 cookie,SYN+ACK 带回 cookie(前 4 字节 e317342e);连接 2、3 的 SYN 带这个 cookie 和 6 字节数据,SYN+ACK 的 ack = SYN 的 seq + 7,数据被接受。然后换成密钥 K2:连接 4 的 SYN 仍带旧 cookie 和数据,服务端不接受——SYN+ACK 的 ack 只有 seq + 1,数据没被确认,同时 SYN+ACK 里带来一个新 cookie(前 4 字节 533701b8);数据在握手之后由客户端重发,服务端应用照样完整收到 hello3。连接 5~7 的 SYN 用新 cookie,数据又被接受。7 条数据全部正确收到。所以密钥轮换的代价是一个连接回到普通握手速度,没有数据丢失,客户端自己换上新 cookie。", t=tl(S(6)), mark=lidx(S(6), '第 4 个'), done=lidx(S(6), '设置 K1', '换成 K2', '第 2 个', '第 3 个', '第 5 个'), kv=KV([['K1 下的连接 2、3', '旧 cookie 有效,数据被接受'], ['换成 K2 后的连接 4', '旧 cookie 被拒,ack = seq + 1,SYN+ACK 带新 cookie'], ['连接 5~7', '新 cookie,数据被接受'], ['7 条数据', '全部收到']], ['换成 K2 后的连接 4'])),
    step("客户端什么时候停用 TFO(这回在 127.77.0.21 上有意去触发)。服务端开 TFO,先无丢包连 3 次:第 1 个 SYN 请求 cookie(0 字节、TFO 选项长 2),第 2、3 个 SYN 带 7 字节数据和 8 字节 cookie。然后用 netlab 开每方向 30% 丢包(单向延迟 20 ms),连 30 次(每次 connectx 带 6 字节),30 次连接都最终成功(失败 0 次)。看每个连接的 SYN 序列:第 1 个 6B/TFO10,一次通过;第 2 个 SYN 丢了,重传的 SYN 变成 0 字节、不再带 TFO 选项;第 3 个又一次通过;第 4、5 个也都是重传成无数据的 SYN;从第 6 个连接起直到第 30 个,SYN 都是 0B 且没有 TFO 选项——客户端已经对这个目的地不再尝试 TFO,连请求 cookie 的选项都没有了。也就是第 2、4、5 个连接的 SYN 各丢失过一次、共 3 次之后,客户端就停用了;“3 次”只是这一次运行里的数,阈值和计数规则没有确认。关掉丢包后每 10 秒连一次、共 36 次(350 秒):SYN 始终是 0B、无 TFO 选项,350 秒内没有恢复。", t=tl(S(7)), mark=lidx(S(7), '丢包第  2 个', '丢包第  4 个', '丢包第  5 个', '丢包第  6 个', '丢包第 30 个'), done=lidx(S(7), '无丢包第 2 个', '无丢包第 3 个', '丢包第  1 个', '丢包第  3 个', '+ 350 s'), kv=KV([['无丢包', '第 2、3 个连接 SYN 带 7 字节'], ['30% 丢包下', '第 2、4、5 个连接的 SYN 重传成无数据'], ['第 6 个连接起', 'SYN 里没有 TFO 选项(已停用)'], ['关掉丢包后 350 秒', '没有恢复']], ['第 6 个连接起'])),
    step("停用的范围与恢复(紧接着第七节,同一个别名 127.77.0.21 仍处于停用状态)。(1)同一个目的地换一个端口,服务端开 TFO,连 3 次:SYN 都是 0B、无 TFO 选项——停用是按目的地址记的,换端口没用。(2)换一个没用过的目的地 127.77.0.22:第 1 个连接 0B/TFO 选项长 2(请求 cookie),第 2、3 个 6B/TFO 选项长 10,一切正常——别的目的地不受影响。(3)继续对 127.77.0.21 每 60 秒连一次,最长 40 分钟,等连续 2 次 SYN 里又带数据:共 41 次,覆盖 2401 秒,每一次 SYN 都是 0B、无 TFO 选项,40 分钟内没有恢复。加上第七节的 350 秒,这个目的地被停用后至少 40 分钟客户端一直没有再尝试;更长的恢复时间、是否要重启或清缓存才能恢复,我没有再等,也没有试 net.inet.tcp.clear_tfocache。", t=tl(S(8)), mark=lidx(S(8), '同一目的地、新端口', '新目的地 127.77.0.22', '+ 2401 s'), done=lidx(S(8), '+    1 s', '+   61 s', '共轮询'), kv=KV([['同一目的地换端口', '仍是 0B、无 TFO 选项'], ['另一个目的地', '正常取 cookie、SYN 带数据'], ['等待 2401 秒', '41 次轮询,没有恢复']], ['等待 2401 秒'])),
    step("Linux 对照(Docker Desktop 的 Linux 虚拟机,内核 7.0.14-linuxkit,两个容器之间每方向 50 ms,往返 100 ms)。客户端 sendto + MSG_FASTOPEN,服务端在 listen 之后设 TCP_FASTOPEN。4 次普通 connect + send:313 / 215 / 213 / 212 ms(第一次多出的约 100 ms 没有追查),中位 214 ms。5 次 TFO:214 / 104 / 111 / 109 / 109 ms——第 1 次 SYN 里没有数据、请求 cookie(SYN 里 TFO 选项长 2,SYN+ACK 带回 cookie),耗时和普通连接一样;后 4 次 SYN 带 2 字节数据和 8 字节 cookie,SYN+ACK 的 ack 确认了数据,中位 109 ms,比普通连接省约 105 ms,就是一个往返。ip tcp_metrics 里有一条带 fo_cookie 的记录;ip tcp_metrics flush 清掉之后,下一个连接又回到请求 cookie(215 ms),再下一个才带数据(102 ms)。Linux 的 cookie 记在内核的 tcp_metrics 里,可以这样清;macOS 上对应的开关是 net.inet.tcp.clear_tfocache,我没有给它免密权限,没有试。", t=tl(S(9)), mark=lidx(S(9), '耗时(ms)', '普通 4 次中位'), done=lidx(S(9), '清掉缓存前', '清掉后', '第 5 个', '第 6 个', '第 10 个', '第 11 个'), b=bars([['普通 connect + send', 214, '214 ms'], ['TFO 第 1 次(取 cookie)', 214, '214 ms'], ['TFO(SYN 带数据)', 109, '109 ms']], 214, mark=[2], done=[0, 1]), kv=KV([['普通连接', '中位 214 ms'], ['TFO 取 cookie', '214 ms,和普通连接一样'], ['TFO SYN 带数据', '中位 109 ms,省约 105 ms'], ['flush 之后', '又回到请求 cookie']], ['TFO SYN 带数据'])),
    step("Linux 客户端缓存着服务端的 cookie(Linux 的 cookie 按目的地址记),把带 cookie 和数据的 SYN 发给同一个地址上没开 TFO 的端口(7001)。3 次的 SYN 都带 2 字节数据和长度 10 的 TFO 选项;服务端内核不认这个选项,SYN+ACK 里没有 TFO 选项,ack = seq + 1,数据没被确认;客户端在握手完成后重发数据,服务端应用依次收到 x0 x1 x2,没有丢也没有重复;3 次耗时 217 / 216 / 214 ms,和普通连接(约 214 ms)一样。也就是说 TFO 对不支持的服务端是安全回退:只是没有省时间。", t=tl(S(10)), mark=lidx(S(10), '第 1 个', '第 3 个'), done=lidx(S(10), '3 次耗时', '服务端(7001)收到的数据'), kv=KV([['SYN', '带 2 字节数据 + 长度 10 的 TFO 选项'], ['SYN+ACK', '无 TFO 选项,ack = seq + 1'], ['数据', '握手后重发,x0 x1 x2 全部到达'], ['耗时', '217 / 216 / 214 ms,和普通连接一样']], ['SYN+ACK'])),
    step("SYN 里的数据会被重放。cookie 是无状态的(只验证“这个客户端地址的 cookie 对不对”),服务端不记得“这个 SYN 来过”。让 Linux 客户端用有效 cookie 发一个带 order-0 的 TFO 连接,从抓包里取出那个 SYN(载荷 7 字节,TFO 选项长度 10),重新计算校验和后,用原始套接字原样重发 5 次(间隔 0.5 秒,源地址还是客户端自己的,相当于路径上的人重放)。服务端内核的 TcpExtTCPFastOpenPassive 计数增加了 5(1 次原始 + 4 次重放),服务端应用读到 order-0 共 5 次,另有 4 条是之后收到客户端 RST 的报错(客户端内核没有对应的套接字,对重放引发的 SYN+ACK 回 RST)。5 次重放里只有 4 次被计数,另一次为什么没有,没有查明。一个坑:容器网卡开着发送校验和卸载,抓到的出站包里 TCP 校验和只是占位值,第一次直接重发时服务端计数 TcpInCsumErrors = 2,重放没有生效,要先重算校验和。这就是规范说 SYN 里的数据可能被重复交付、所以 TFO 只适合幂等请求的原因。", t=tl(S(11)), mark=lidx(S(11), '服务端内核计数', '服务端应用收到的记录', '其中应用读到'), done=lidx(S(11), '(容器网卡', '抓到的 SYN'), kv=KV([['原始连接', '1 次'], ['原样重放的 SYN', '5 次,其中 4 次被服务端接受'], ['服务端应用读到 order-0', '共 5 次'], ['结论', 'SYN 里的数据可以被重复交付']], ['服务端应用读到 order-0'])),
    step("中间设备丢弃“带数据的 SYN”(在服务端容器上用 iptables 丢弃长度 ≥ 70 字节的 SYN,不带数据的 SYN 约 60 字节、请求 cookie 的约 64 字节)。Linux 客户端有有效 cookie,连续 5 次 TFO:每次第一个 SYN(2 字节数据)被丢掉,约 1.0 秒后重传的 SYN 变成 0 字节、没有数据,连接这才建立;5 次耗时 1269 / 1228 / 1229 / 1227 / 1231 ms(正常 TFO 约 109 ms,普通连接约 214 ms),也就是每个连接白等一个重传超时。5 次都是这样,Linux 客户端没有因为连续失败而不再尝试——这个虚拟机内核里 tcp_fastopen_blackhole_timeout_sec 是 0(黑洞检测没启用),TcpExtTCPFastOpenBlackhole 计数为 0,所以这不是 Linux 默认配置下的结论。撤掉规则后紧接着的 3 次立刻回到 106 / 106 / 103 ms。对比 macOS(第七节):同样的“SYN 带数据收不到回应”,macOS 在 3 次重传之后对该目的地停用 TFO,并且至少 40 分钟没有恢复(第八节)。", t=tl(S(12)), mark=lidx(S(12), '丢弃期间 5 次耗时', '第 1 个连接的 SYN', '第 5 个连接的 SYN'), done=lidx(S(12), 'tcp_fastopen_blackhole_timeout_sec', '第 6 个连接的 SYN', '第 8 个连接的 SYN', '客户端内核计数', '服务端收到的数据'), b=bars([['TFO 正常', 109, '109 ms'], ['普通 connect + send', 214, '214 ms'], ['SYN 带数据被丢弃', 1229, '1229 ms']], 1229, mark=[2], done=[0, 1]), kv=KV([['被丢弃的 SYN', '2 字节数据 + cookie'], ['重传的 SYN', '约 1.0 秒后,0 字节、无数据'], ['5 次耗时', '约 1.23 秒'], ['撤掉规则后', '立刻回到约 105 ms']], ['5 次耗时'])),
]
A = mkartw('w60', 60, '网络协议,TCP,TCP Fast Open,TFO,connectx,SYN,cookie,真实验证,动画演示',
    '实测 TCP Fast Open:macOS 上服务端 listen 后才能设选项、客户端用 connectx;cookie 与 SYN 带数据、50 ms 延迟下 202 ms 降到 101 ms、example.com 接受 SYN 里的请求;服务端密钥轮换后旧 cookie 被拒、数据不丢;客户端在 SYN 重传 3 次后对该目的地停用 TFO,停用只针对该目的地、至少 40 分钟没有恢复;Linux 容器对照:省一个往返、对不支持的服务端回退、SYN 数据可被重放、带数据的 SYN 被丢弃时每个连接多等约 1 秒。',
    'TCP Fast Open 想把“握手一个往返 + 请求应答一个往返”压成一个往返:第一次连接拿一个 cookie,以后的连接把数据直接塞进 SYN。这篇先在 macOS 上实测它在线上长什么样、能省多少时间、公网上谁支持,再用 root 权限补上密钥轮换和“客户端为什么悄悄不用了”,最后在 Linux 容器里对照 Linux 的行为、重放和被中间设备丢弃的情形。',
    [('202 → 101 ms', '50 ms 单向延迟的链路上,普通 connect + send 与 SYN 带数据的 connectx 的耗时中位数'), ('3 次重传后停用', 'macOS 在 SYN 带数据重传 3 次后对该目的地不再发 TFO 选项,至少 40 分钟没有恢复'), ('5 次', '被重放的 SYN 让 Linux 服务端应用读到同一份数据的次数(含原始 1 次)')],
    [('开关与调用方式', '<p>net.inet.tcp.fastopen=3;服务端要在 listen() 之后设 TCP_FASTOPEN;客户端用 connectx 带数据(Python 需要 ctypes)。</p>'),
     ('服务端不支持时', '<p>用一个客户端从没用过的目的地做对照:8 次连接的 SYN 都是 0 字节、带长度 2 的 TFO 选项请求 cookie,服务端不回 TFO 选项,数据在握手后才发。</p>'),
     ('cookie 与 SYN 带数据', '<p>第一个连接请求 cookie(TFO 选项长 2);之后的连接 SYN 带 8 字节 cookie(选项长 10)和数据,SYN+ACK 的 ack 确认了数据。</p>'),
     ('省下一个往返', '<p>50 ms 单向延迟下,普通连接 202 ms,带数据的 TFO 连接 101 ms。</p>'),
     ('公网服务器', '<p>example.com 接受 SYN 里的 56 字节请求并确认,首字节比普通连接快约一个 RTT。</p>'),
     ('服务端密钥轮换', '<p>换密钥之后,旧 cookie 被拒,SYN+ACK 的 ack 只有 seq + 1 并带来新 cookie,数据在握手后重发,不丢;下一个连接起用新 cookie。</p>'),
     ('客户端悄悄停用', '<p>30% 丢包下,SYN 带数据的重传 3 次之后,客户端对该目的地不再发 TFO 选项;丢包关掉后至少 40 分钟没有恢复。</p>'),
     ('停用的范围与恢复', '<p>停用是按目的地址记的:同一目的地换端口仍不尝试,别的目的地不受影响;之后每 60 秒试一次,共 41 次、覆盖 2401 秒,没有恢复。</p>'),
     ('Linux:省一个往返', '<p>同样 100 ms 往返,Linux 的 TFO 连接中位 109 ms,普通连接 214 ms;ip tcp_metrics flush 清掉缓存后又要重新取 cookie。</p>'),
     ('对不支持的服务端', '<p>Linux 客户端把 cookie 和数据发给没开 TFO 的端口:数据没被确认,握手后重发,不丢不重,耗时与普通连接一样。</p>'),
     ('SYN 里的数据可被重放', '<p>原样重发抓到的 SYN,服务端应用又读到同一份数据:5 次读取里有 4 次来自重放。所以只适合幂等请求。</p>'),
     ('被中间设备丢弃', '<p>带数据的 SYN 被丢掉时,Linux 约 1 秒后重传无数据的 SYN,每个连接多等约 1.0 秒;这个内核里的黑洞检测没启用,连续 5 次都是这样。</p>')],
    steps,
    [ENV_W + '。第一、三、四、五节来自较早的一次运行(lo0 和 example.com:80 各 3 次,第四节加了 netlab 每方向 50 ms);第二、六、七、八节在 lo0 的别名 127.77.0.N 上,别名的增删和 net.inet.tcp.fastopen_key 的设置通过一个只允许这几件事的免密 root 脚本完成,第七节用 netlab 开了 30% 丢包、单向 20 ms;第九到十二节在 Docker Desktop 的 Linux 虚拟机里的两个容器之间(内核 7.0.14-linuxkit,eth0 上 netem 每方向 50 ms),第十二节用 iptables 丢弃长度 ≥ 70 字节的 SYN 模拟中间设备',
     '没有验证:macOS 客户端停用 TFO 的确切阈值和计数规则(只在 30% 丢包的一次运行里看到,SYN 带数据重传 3 次后停用);net.inet.tcp.clear_tfocache 能否清除这种停用(没有给它免密权限,没有试);cookie 的有效期和自动轮换周期(只试了手动换密钥);macOS 作为服务端时对 SYN 重放的反应(重放实验只在 Linux 容器里做,5 次重放里 1 次没有被计数,原因没有查明);Linux 内核的黑洞检测(这个虚拟机里该开关是 0,没有启用);公网上经过真实中间设备(NAT、防火墙)时 SYN 带数据的处理,这里只用 iptables 模拟;HTTP / TLS 之上的实际收益(TCP 握手之后 TLS 还要多个往返,TFO 只省 TCP 握手那一个)'],
    'TCP Fast Open')
